// src/WalletPage.js
import React, { useState } from 'react';
import { Wallet, JsonRpcProvider, formatEther } from 'ethers';

function WalletPage() {
  const [privateKey, setPrivateKey] = useState('');
  const [wallet, setWallet] = useState(null);
  const [balance, setBalance] = useState(null);
  const [error, setError] = useState('');

  const connectWallet = async () => {
    try {
      const provider = new JsonRpcProvider('https://eth.public-rpc.com'); // public Ethereum mainnet RPC
      const userWallet = new Wallet(privateKey, provider);

      const ethBalance = await provider.getBalance(userWallet.address);
      const formattedBalance = formatEther(ethBalance);

      setWallet(userWallet);
      setBalance(formattedBalance);
      setError('');
    } catch (err) {
      console.error(err);
      setError('Invalid private key or connection issue.');
      setWallet(null);
      setBalance(null);
    }
  };

  return (
    <div className="wallet-page" style={{ padding: '20px', maxWidth: '600px', margin: 'auto' }}>
      <h1>🔐 Wallet Access</h1>

      {!wallet && (
        <>
          <textarea
            rows="4"
            placeholder="Paste your private key here"
            value={privateKey}
            onChange={(e) => setPrivateKey(e.target.value)}
            style={{ width: '100%', padding: '10px', fontSize: '16px' }}
          />
          <br />
          <button onClick={connectWallet} style={{ marginTop: '10px', padding: '10px 20px' }}>
            Connect Wallet
          </button>
          {error && <p style={{ color: 'red' }}>{error}</p>}
        </>
      )}

      {wallet && (
        <div style={{ marginTop: '20px' }}>
          <p><strong>Wallet Address:</strong><br />{wallet.address}</p>
          <p><strong>ETH Balance:</strong> {balance} ETH</p>
        </div>
      )}
    </div>
  );
}

export default WalletPage;
